1. Write a function named CardinalToOrdinal that converts a cardinal int
value into an ordinal string value; for example, it converts 1 into 1st, 2 into
2nd, and so on, as shown in the following code:
static string CardinalToOrdinal(int number)
{
switch (number)
{
case 11:
case 12:
case 13:
return $"{number}th";
default:
string numberAsText = number.ToString();
char lastDigit = numberAsText[numberAsText.Length - 1];
string suffix = string.Empty;
switch (lastDigit)
{
case '1':
suffix = "st";
break;
case '2':
suffix = "nd";
break;
case '3':
suffix = "rd";
break;
default:
suffix = "th";
break;
}
return $"{number}{suffix}";
}
}
static void RunCardinalToOrdinal()
{
for (int number = 1; number <= 40; number++)
{
Write($"{CardinalToOrdinal(number)} ");
}
WriteLine();
}
